export type SourceId = keyof typeof sources;

export interface Source {
  readonly id: string;
  readonly publisher: string;
  readonly title: string;
  readonly url: string;
  readonly kind: "manufacturer-specification" | "manufacturer-announcement" | "manufacturer-catalogue";
  readonly publishedAt?: string;
  readonly accessedAt: string;
}
export interface SourcedValue<T> {
  readonly value: T;
  readonly sourceIds: readonly SourceId[];
  readonly qualification?: string;
}

export interface SourcedDate extends SourcedValue<string | null> {
  readonly basis?: "availability" | "announcement";
}

export interface PhoneRecord {
  readonly slug: string;
  readonly maker: SourcedValue<string>;
  readonly model: SourcedValue<string>;
  readonly generation: SourcedValue<"current" | "earlier">;
  readonly formFactor: SourcedValue<"slab" | "thin-slab" | "book-fold" | "flip-fold">;
  readonly releasedOn: SourcedDate;
  readonly originalPrice: SourcedValue<{
    readonly amount: number | null;
    readonly currency: string | null;
    readonly market: string;
    readonly configuration: string;
  }>;
  readonly display: {
    readonly size: SourcedValue<string>;
    readonly panel: SourcedValue<string | null>;
    readonly resolution: SourcedValue<string>;
    readonly refreshRate: SourcedValue<string | null>;
    readonly peakBrightness: SourcedValue<string | null>;
  };
  readonly secondaryDisplay?: SourcedValue<string>;
  readonly weight: SourcedValue<string | null>;
  readonly storage: SourcedValue<{
    readonly options: string;
    readonly startsAtGb: number | null;
  }>;
  readonly configurations?: SourcedValue<string>;
  readonly colors?: SourcedValue<string>;
  readonly dimensions?: SourcedValue<string>;
  readonly charging?: SourcedValue<string>;
  readonly processor: SourcedValue<string | null>;
  readonly rearCameras: SourcedValue<string>;
  readonly batteryClaim: SourcedValue<string>;
  readonly resistance: SourcedValue<string | null>;
}

